sma_trend.source:
"""Slow trend baseline; hold while fast SMA exceeds slow SMA."""
from strategy.indicators import sma

DEFAULTS = {"fast": 50, "slow": 200}


def generate_signals(prices, fast=50, slow=200):
    if not 1 <= fast < slow:
        raise ValueError("Require 1 <= fast < slow")
    return (sma(prices.close, fast) > sma(prices.close, slow)).astype(int)

rsi_pullback.source:
"""Buy oversold pullbacks only above the long-term trend."""
from strategy.indicators import positions, rsi, sma

DEFAULTS = {"period": 14, "entry": 30, "exit": 55, "trend": 200, "max_holding": 20}


def generate_signals(prices, period=14, entry=30, exit=55, trend=200, max_holding=20):
    if not (period > 0 and trend > 0 and 0 < entry < exit < 100 and max_holding > 0):
        raise ValueError("Invalid RSI parameters")
    value, average = rsi(prices.close, period), sma(prices.close, trend)
    return positions((value < entry) & (prices.close > average),
                     (value >= exit) | (prices.close < average), max_holding)

bollinger_reversion.source:
"""Enter after price recovers through the lower band, exit at the middle band."""
from strategy.indicators import positions, sma

DEFAULTS = {"period": 20, "deviations": 2.0, "max_holding": 20}


def generate_signals(prices, period=20, deviations=2.0, max_holding=20):
    if period < 2 or deviations <= 0 or max_holding <= 0:
        raise ValueError("Invalid Bollinger parameters")
    mid = sma(prices.close, period)
    lower = mid - deviations * prices.close.rolling(period).std(ddof=0)
    enter = (prices.close.shift(1) < lower.shift(1)) & (prices.close >= lower)
    return positions(enter, prices.close >= mid, max_holding)

macd_trend.source:
"""MACD bullish state filtered by positive MACD and a long-term SMA."""
from strategy.indicators import ema, sma

DEFAULTS = {"fast": 12, "slow": 26, "signal": 9, "trend": 200}


def generate_signals(prices, fast=12, slow=26, signal=9, trend=200):
    if not (1 <= fast < slow and signal > 0 and trend > 0):
        raise ValueError("Invalid MACD parameters")
    line = ema(prices.close, fast) - ema(prices.close, slow)
    trigger = ema(line, signal)
    return ((line > trigger) & (line > 0) & (prices.close > sma(prices.close, trend))).astype(int)

donchian_breakout.source:
"""Close above prior channel high on elevated volume; exit below prior low."""
from strategy.indicators import positions

DEFAULTS = {"entry_window": 55, "exit_window": 20, "volume_window": 20, "volume_multiple": 1.5}


def generate_signals(prices, entry_window=55, exit_window=20, volume_window=20, volume_multiple=1.5):
    if min(entry_window, exit_window, volume_window) < 1 or volume_multiple <= 0:
        raise ValueError("Invalid Donchian parameters")
    high = prices.high.rolling(entry_window).max().shift(1)
    low = prices.low.rolling(exit_window).min().shift(1)
    volume = prices.volume.rolling(volume_window).mean().shift(1)
    return positions((prices.close > high) & (prices.volume > volume * volume_multiple), prices.close < low)

